test("five-actor dispatch stops after maxConsecutiveRefusals with exactly two dispatch calls and all actors refused", async () => {
  const territory = fixture(), ledgerRoot = join(territory, "trajectory-ledger");
  let dispatchCalls = 0;
  const dispatch = async (jobs) => {
    dispatchCalls += 1;
    return jobs.map((job) => ({ id: job.id, refusal: { type: "no-feasible-endpoint" }, attempts: [] }));
  };
  const result = await runMission({
    id: "urn:test:mission:five-actor-circuit",
    objective: "Repair the add function so the declared test passes.",
    territory,
    verifyCommand: "node --test calc.test.mjs",
    actors: 5,
    maxRounds: 5,
    maxConsecutiveRefusals: 2,
    apply: false,
  }, { dispatch, ledgerRoot });

  assert.equal(result.outcome.verified, false);
  assert.equal(result.metrics.verifiedCandidates, 0);
  assert.equal(dispatchCalls, 2);
  assert.equal(result.metrics.rounds, 2);
